    'Please enter your debtor/customer number of your laboratory in the field "Customer number". You can find this, for example, on your previous analyses or invoices.',
  'lufa_speyer.name': 'LUFA Speyer',
  'lufa_speyer.description':
    'This plugin establishes the connection to the feed laboratory of the LUFA Speyer.',
