    'Please enter your debtor/customer number of your laboratory in the field "Customer number". You can find this, for example, on your previous analyses or invoices.',
  'cow_connect.name': 'CowConnect',
  'cow_connect.description': `The CowConnect Box is a hardware solution that can be retrofitted to feed mixer wagons. It collects data on feed consumption, feed efficiency and feed costs. The data can be called up via the cloud at any time using an app. <br><br> <strong> Functionality: </strong> <ol> <li> The fodjan interface transfers your rations directly to the CowConnect cloud. CowConnect brings the values to the mobile box on the feed mixer. </li> <li> The transferred ration / recipe is displayed on the CowCconnect hardware. Mixing of the feed and feeding can begin. </li> <li> The rations actually fed are sent to the CowConnect Cloud and enter the system via the CowConnect interface to fodjan. </li> </ol> <br> <strong> Calculation: </strong> <br> No calculations necessary <br> <br> <strong> Special features: </strong> <br> Since fodjan does not yet have a "pen" or "location management" to manage a group of animals, that is fed at different locations, recipes / rations are only ever handed over for one group of animals. The assignment to the pens is carried out by CowConnect.<br><br>'`,
  'cow_connect.input_description':
    "To connect to CowConnect you first have to establish the connection between fodjan and CowConnect. To do this, log into the CowConnect portal and go to the interfaces area. Insert the FARM UID displayed here at Fodjan and activate the interface.'",
  'mmm_feednow.name': "MmmooOgle FeedNow!'",
  'mmm_feednow.description':
    "The interface to MmmooOgle FeedNow! makes it possible to transfer rations from fodjan to MmmooOgle FeedNow!. This allows you to feed as usual with your feed mixer wagon and the MmmooOgle FeedNow! hardware on it. The measured data (e.g. on the quantities loaded) are automatically returned to your documentation and evaluations in fodjan (e.g. feed costs, consumption, mixing accuracy, feed efficiency, etc. - More about the evaluations in our help section.'",
  'mmm_feednow.input_description': "'",
  'dinamica_generale.name': "Dinamica Generale'",
  'dinamica_generale.description':
    "The interface to products from Dinamica Generale enables the integration of precise feeding data. In addition to the quantities of feed actually fed, the NIRS sensors provide information on the exact composition of the feed. <br><br> <strong> Functionality: </strong> <br> <ol> <li> The fodjan interface transfers your rations directly Mixer feeders equipped with Dinamica Generale scales. </li> <li> The transferred ration / recipe accompanies the mixing and feeding process. </li> <li> The fed rations are then transferred to fodjan. </li> </ol><br> <strong> Calculation: </strong> <br> No calculations necessary<br><br>'",
  'dinamica_generale.input_description':
    'In order to connect to Dinamica Generale you must first establish the connection between fodjan and Dinamica Generale. To do this, log into the DTM portal and go to the interfaces area. Insert the FARM UID displayed here at Fodjan and activate the interface.',
  'lab_rosenau.name': 'Futtermittellabor Rosenau',
  'lab_rosenau.description':
    'This plugin connects to the feed laboratory in Rosenau.',
  'lab_rosenau.input_description':
    'With the following three steps you activate your lab interface:<br><br><strong>Features:</strong><br><ol><li>Please enter your customer number of your laboratory in the field "Customer number". You can find this, for example, on your previous analyses or invoices.</li><li> Activate this plugin by clicking on the "Activate" button. Your feed analyses from Rosenau can now be transferred directly to fodjan.</li><li>If you use the sample accompanying bill from fodjan, then we automatically get a copy of all your analyses directly from the laboratory to make them available to you in fodjan under "Feed analyses". </li></ol>',
