  Trockenmasseaufnahme: 'Dry matter intake',
  'Bitte beachten Sie das neu hinzugefügte Futtermittel in der Futterküche im T4C anzupassen. Das betrifft folgende Futtermittel:':
    'Be aware of adjusting the feed kitchen with the new feedstuff. This concerns the following feedstuffs:',
  'Futtermittel ersetzen': 'Replace feedstuff',
  'Futtermittel in Rationen ersetzen': 'Replace feedstuff in rations',
  'Wählen Sie aus, welches Futtermittel durch ein anderes ersetzt werden soll. Des Weiteren können Sie bestimmen ab welchem Datum dieses gelten soll.':
    'Select which feed should be replaced by another. Furthermore, you can determine from which date this should apply.',
  'In Rationen, welche zu einem späteren Zeitpunkt angefangen werden zu füttern, als das gewählte Datum, wird das ausgewählte Futtermittel mit gleicher Menge ersetzt.':
    'In rations which are started later than the chosen date, the selected feed will be replaced with the same amount.',
  'Bei Rationen, welche zum gewählten Zeitpunkt in der Fütterung sind, wird ab diesem Datum eine neue Ration erstellt (Kopie), in der das gewählte Futtermittel ersetzt wird.':
    'In rations, which are at the selected time in feeding, will from that date a new ration created (copy) in which the selected feedstuff will be replaced.',
