  'lkvs_trouw.description':
    '<p>This plugin establishes the connection to the feed laboratory of the LKV Saxony.<p>',
  'lkvs_trouw.input_description':
    '<p>Please enter here the LKS customer number of the farmer, which can be found on the Trouw sample form under "sampler.<p>',
  'bvl2_df.description':
    'The V-DAIRY Feeder Box works with all makes of feed mixers. The synchronization with the online service TMR-Pilot is carried out by means of a PDA.<br><br><strong>Functionality:</strong><br><ol><li>The fodjan interface transfers your rations directly to the online service of BvL.</li><li>If you receive the message "Some components still have to be assigned" when transferring the data, please log into the web interface of the Dairyfeeder, click on the menu item <font class="italic">Interfaces</font> and <font class="italic">fodjan</font> and click on <font class="italic">edit</font> in the table displayed there.</li><li>The ration should now be available on the PDA of the feed mixer. </li></ol><br><br><strong>Calculation:</strong><br>All feed quantities are exported in fresh mass including residual feed and divided by the number of feeds per day.',
