  'So löschen Sie einen Betrieb': 'How to delete a farm',
  'Nach dem Ausfüllen dieses Formulars werden Sie automatisch als <strong>Benutzer mit Admin-Rechten</strong> für den angelegten Betrieb zugewiesen. Damit haben Sie vollen Zugriff z. B. auf die Anpassung des Futtermodells oder der Schnittstellen.':
    'After completing this form you will be automatically assigned as a <strong>user with admin rights</strong> to the created farm. This gives you full access e.g. to adapt the feed model or interfaces.',
  'Nachdem Sie den Betrieb erfolgreich eingerichtet haben, werden Sie auf die Seite zur Verwaltung weitergeleitet. Nun öffnet sich die <strong>Schnittstellen-Verwaltung</strong>. Dort können Sie festlegen, welche Futterdatenbank geladen werden soll oder welche Schnittstelle aktiviert werden soll.':
    'After you have successfully set up the farm you will be directed to the page for managing the new farm. Now <strong>plugin administration opens</strong>. There you can specify which feed database to load or which interface to activate.',
  'Zuletzt können Sie festlegen, <strong>welche Benutzer Sie einladen möchten</strong>, um Zugriff auf den Betrieb zu erhalten.':
    'Lastly you can specify <strong>which users you want to invite to have access</strong> to the farm.',
  '<strong>Hinweis:</strong> In der Testphase können Sie nur 3 Betriebe anlegen. Derzeit haben Sie %s%/3.':
    '<strong>Note:</strong> During the test phase, you can only create 3 farms. Currently you have %s%/3.',
