  'Fütterungsmanagement für Profis': 'Feeding Management for Professionals',
  'Sie wollen nicht nur den Überblick über Ihr Futtermanagement, sondern auch genaue Auswertungen, um besser zu wirtschaften? Dann ist fodjan Pro die richtige Wahl. Um unsere Software kennenzulernen, bieten wir Ihnen an, sie die ersten <strong>2 Wochen kostenlos</strong> zu testen':
    'You do not only want an overview of your feed management, but also precise evaluations in order to improve your business? Then fodjan Pro is the right choice. To get to know our software, we offer to test it for the first <strong>2 weeks for free </strong>',
  'Mobiles Fütterungsmanagement': 'Mobile Feeding Management',
  'Sie wollen Ihren Betrieb mit einfachen Mitteln verbessern und Ihre Fütterung auf Tiergesundheit, Wirtschaftlichkeit und Leistungsfähigkeit schnell checken? Dann ist die flexible fodjan App die richtige Wahl. Testen Sie unsere <strong>aktuelle Version jetzt kostenlos.</strong>':
    'You want to improve your farm with simple means and quickly check your feeding on animal health, efficiency and performance? Then the flexible fodjan app is the right choice. Try our <strong>latest version now for free.</strong>',
