  'Sagen Sie uns Ihre Meinung!': 'Tell us your opinion!',
  'Hier finden Sie alle Infos zur fodjan GmbH - dem Entwickler der intelligenten Fütterungssoftware. Mehr Infos hier.':
    'Here you can find all information about fodjan GmbH - the developer of the intelligence feeding software.',
  'Die fodjan Story': 'The fodjan story',
  'Die Fakten': 'The facts',
  'Internetbasierte Software für Futtermanagement und zur Rationsberechnung von Milchkühen':
    'Internet-based software for feed management and ration calculation of dairy cows',
  Gründung: 'Founding',
  Gründer: 'Founder',
  'Publiziert am': 'Published on',
  'fodjan smart feeding': 'fodjan smart feeding',
  'Die neue Generation der Rationsberechnung':
    'The new generation of ration calculation',
  'Die fodjan GmbH wurde im September 2014 in Dresden gegründet. Carsten Gieseler, Geschäftsführer der fodjan GmbH, entwickelte die Idee für die smart feeding Software während seines Agrar – und Betriebswirtschaftsstudiums. In Zusammenarbeit mit dem Informatiker Johannes Völker, dem Betriebswirt Michael Schütze, dem Webentwickler Daniel Schreck und dem Algorithmus-Spezialist Paul Völker entwickelte das Team die Software bis zur Marktreife und testete die Pilotversion erfolgreich in mehreren großen landwirtschaftlichen Betrieben.':
    'fodjan GmbH was founded in Dresden in September 2014. Carsten Gieseler, one company’s managing directors, developed the idea for smart feeding software during his own university studies in agriculture and business administration. He joined with IT specialist Johannes Völker, business administration expert Michael Schütze, web designer Daniel Schreck and algorithm engineer Paul Völker to develop the software up to market readiness, including successful tests of the pilot version at several large agricultural operations.',
  'Impressum. Kontaktdaten und weitere nützliche Infos zu fodjan, der Softwarelösung der modernen Rationsberechnung.':
    'Imprint. Contact details and further information about fodjan, the software solution of modern ration calculation.',
