  'Als neues Futtermittel anlegen': 'Create as new feedstuff',
  'Futtermittel aus der Datenbank nutzen oder vorhandenes aus dem Bestand überschreiben':
    'Use feedstuff from database or overwrite existing feedstuff from stock',
  'Beim Eintippen zeigen wir Ihnen Vorschläge von Futtermitteln aus Ihrem Bestand bzw. Ihrer aktivierten Datenbank an. Wählen Sie ein vorhandenes Bestandsfuttermittel, wird dieses überschrieben und alle Rationen, die dieses enthalten, neu bewertet. Wählen Sie ein Datenbankfuttermittel, wird dieses Ihrem Bestand hinzugefügt. In beiden Fällen heißt überschreiben, dass Werte mit denen der Analyse aktualisiert und nicht attestierte Werte belassen werden.':
    'As you type, we show you suggestions of feed from your stock and your activated database. If you select an existing feed, it will be overwritten and all rations containing it will be re-evaluated. If you select a database feed, it will be added to your stock. In both cases, overwriting means updating values with those of the analysis and leaving unattested values.',
  'Futtermittel aus der Datenbank nutzen': 'Use feedstuff from database',
  'Beim Eintippen zeigen wir Ihnen Vorschläge von Futtermitteln aus ihrer aktivierten Datenbank an. Das Datenbankfuttermittel wird dann Ihrem Bestand hinzugefügt.':
    'As you type, we will show you suggestions of feeds from their activated database. The database feed is then added to your stock.',
