  'Laden Sie hier eine _filename_-Datei hoch. Wir prüfen Ihre Kundennummer, die Sie dann zur Einrichtung der MLP-Schnittstelle übernehmen können.':
    'Upload a _filename_ file here. We will check your customer number, which you can then use to set up the milk report interface.',
