  'cost_kg_milk_estimated.name': 'Costs per kg milk (adjusted)',
  'Sie haben ein neues Mischfutter erstellt. Das originale Futtermittel wird in verschiedenen Rationen benutzt. Wollen Sie das originale Futtermittel mit dem neu erstellten ersetzen oder wollen Sie das neue Futtermittel nur zum Bestand hinzufügen?':
    'You have created a new compound feed. The original feedstuff is used in different rations. Do you want to replace the original feed with the newly created one, or do you only want to add the new feed to the stock?',
  'Hinweis:': 'Note:',
  "Sie können Futtermittel auch mit der Funktion 'Futtermittel ersetzen' auf der Seite des Bestands ersetzen.":
    'You can also replace feed with the "Replace feedstuff" feature on the stock page.',
  'Rationen werden geladen': 'Rations are loaded',
  'Wie wollen Sie das Mischfutter speichern?':
    'How do you want to save the Compound feed?',
  'Was ist das Futtermittelarchiv?': 'What is the feedstuff archive?',
  'Mehr lesen in neuem Tab': 'Read more in new tab',
  'In den Bestand aufnehmen und als Vorschau in der Ration anzeigen':
    'Include in the stock and show as a preview in the ration',
  'Ab sofort für alle Rationen ersetzen (außer vergangene gefütterte Rationen)':
    'Replace for all rations feeded from today (except past fed rations).',
  'Ab hier eingestelltem Datum in allen Rationen ersetzen (außer vergangene gefütterte Rationen)':
    'Replace from date set here in all rations (except past fed rations).',
  'Ich bin mir sicher, dass das Futtermittel in den genannten Rationen ersetzt werden soll. Das originale Mischfutter wird archiviert.':
    'I am sure that the feed is to be replaced in the rations mentioned. The original compound feed is archived.',
  'Ich bin mir sicher, dass das Futtermittel in den genannten Rationen ersetzt werden soll. Das originale Mischfutter bleibt im Bestand.':
    'I am sure that the feed is to be replaced in the rations mentioned. The original compound feed remains in the stock.',
  'Das Mischfutter wird in den Bestand aufgenommen und in dieser Ration angezeigt, nachdem Sie unten auf "Mischfuttern speichern" geklickt haben. <br/><br/>Es wird der Ration jedoch erst mit dem Speichern der Ration hinzugefügt. Bis dahin können Sie die Rationsbearbeitung noch abbrechen, wodurch das bisherige Mischfutter in der Ration wiederhergestellt wird. <br/><br/>Das originale Mischfutter wird daher <u>nicht archiviert</u>.':
    'The compound feed is added to the stock and displayed in this ration after clicking "Save compound feed" at the bottom. <br/><br/>However, it will not be added to the ration until the ration is saved. Until then, you can still cancel the ration processing, which will restore the previous compound feed in the ration. <br/><br/>The original compound feed is therefore <u>not archived</u>.',
  'Das originale Mischfutter wird <u>archiviert</u>. Ab Speicherung überschreibt dieses Mischfutter das vorherige Mischfutter in allen Rationen, außer in Rationen, die in der Vergangenheit gefüttert wurden, jetzt aber nicht mehr aktiv sind. In diesen wird weiterhin das archivierte Mischfutter angezeigt.':
    'The original compound feed is <u>archived</u>. From the moment it is saved, this compound feed overwrites the previous one in all rations, except in rations that were fed in the past but are no longer active. In these, the archived one will continue to be displayed.',
  'Ab dem gesetzten Datum überschreibt dieses Mischfutter den vorherigen Stand des Mischfutters in allen Rationen, außer in Rationen, die in der Vergangenheit gefüttert wurden, jetzt aber nicht mehr aktiv sind. In diesen wird weiterhin das archivierte Mischfutter angezeigt. Das originale Mischfutter wird <u>nicht archiviert</u>.':
    'From the set date, this compound feed overwrites the previous compound feed in all rations, except in rations that were fed in the past but are no longer active. In these, the archived one will continue to be displayed. The original compound feed is <u>not archived</u>.',
  'Beim Abrufen der Daten ist etwas schiefgelaufen. Bitte versuchen Sie es später noch einmal.':
    'Something went wrong while retrieving the data. Please try again later.',
  'Sie besitzen keine gültige fodjan Pro Lizenz.':
    'You do not have a valid fodjan Pro license.',
