  'Vergleich Vormonate': 'Comparison Previous months',
  'Milch Gesamt': 'Total milk',
  'mlp.urea.warning':
    'Urea content is an indicator of protein supply to the dairy cow. The optimum urea content (180 mg/l to 230 mg/l) is given today from the point of view of lower nitrogen input into the environment. This value can go up by using unprotected feed urea or be reduced by using protected protein.',
  'mlp.energy_deficiency.warning':
    'To detect an energy deficiency situation in the herd, the fat-protein quotient (F:P > 1.5) and the assessment of protein supply (depending on milk yield) are used. If one of these parameters is met, the cow is in an energetic undersupply.  Consequences may include fertility problems, reduced milk yield, subclinical ketosis, or a depletion of body reserves, especially during the first 30 days of lactation.',
  'mlp.rumen_health_risk.warning':
    'Especially at the beginning of lactation and with a physiologically lower feed intake, there is a risk of rumen over-acidification (low milk fat content). Individual cows are very productive and healthy despite low fat content (skim milk). These cows manage their energy excretion very intelligently by producing less fat. Other cows tend to become over-acidified, especially if the basic feed intake is too low compared to the concentrated feed. The goal should always be for the cow to consume at least 60% basic feed.',
  'mlp.ketosis_risk.warning':
    'Ketosis is suspected in the herd when the fat-protein ratio is too high (F:P > 1.5) and, at the same time, the protein content is too low in relation to the milk yield. This energetic undersupply leads to ketosis over a longer period of time, especially in the first weeks of lactation. Other consequences can include emaciation, a sharp drop in feed intake, fatty liver and an increased occurrence of ketone bodies in the urine and blood.',
  'mlp.obesity_risk.warning':
    'The milk protein content at the end of lactation is one of the best key figures to determine obesity of cows. Due to the high heritability of this parameter, it must be taken into account that "high protein" cows have a significantly higher milk protein content at the end of lactation than "low protein" cows. This means that if the protein content increases by more than 0.6 percentage points compared to the average of the previous 200 lactation days of the cow, there is a risk of obesity.',
  'MLP-Auswertung': 'MLP-Analysis',
  Vergleich: 'Comparison',
  'Kein Vergleich': 'No comparison',
  Jahresdurchschnitt: 'Yearly average',
  Laktation: 'Lactation',
  'Anteil an melkenden Tieren': 'Proportion of animals milking',
  'Harnstoff in der Milch': 'Urea in milk',
  'Mischfutter auswählen': 'Choose compound feed',
  'Futtermittel auswählen': 'Choose feedstuff',
  Rezeptur: 'Recipe',
  'PDF Manager': 'PDF Manager',
  'Auffällige Tiere': 'Suspicious animals',
  'MLP - Monatsbericht': 'MLP - monthly report',
  'Anhand der Milchinhaltsstoffe gibt Ihnen NutriCheck Rückschlüsse auf die Gesundheit und die Fütterung Ihrer Kühe. Die aus der MLP vorliegenden Daten von Eiweiß, Fett, Harnstoff und dem Fett-Eiweiß-Quotient werden hierbei in Abhängigkeit der Milchleistung pro Einzeltier betrachtet. Das Ergebnis ist eine Risikoeinschätzung Ihrer Herde hinsichtlich Ketose, Pansengesundheit (Azidose), Energiemangel und Verfettung. Die Beurteilung dieser Parameter kann eine wichtige Stellschraube sein, um Ihren Betriebserfolg zu optimieren.':
    'Based on the milk ingredients, NutriCheck gives you conclusions about the health and feeding of your cows. The data available from the MLP with regard to protein, fat, urea and the fat-protein ratio are thereby considered in relation to the milk yield per individual animal. The result is a risk assessment of your herd in terms of ketosis, rumen health (acidosis), energy deficiency and adiposity. The assessment of these parameters helps to optimize your farm success.',
