  'SCHAUMANN steht weltweit für Erfolg im Stall. Seit der Firmengründung 1938.':
    'SCHAUMANN stands for success in the barn worldwide. Since the company was founded in 1938.',
  'SCHAUMANN hat sein Schweine-Produktprogramm für Sauen, Ferkel und Mastschweine neu geordnet und stellt die drei klar strukturierten Mineralfutterlinien vor.  ':
    'SCHAUMANN has reorganised its pig product range for sows, piglets and fattening pigs and presents the three clearly structured mineral feed lines.',
